"use strict";
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt = (n, digits=0) => n == null ? "—" : Number(n).toLocaleString("vi-VN", {maximumFractionDigits:digits});
const pages = {overview:"Tổng quan",explorer:"Tra cứu pin",audit:"Kiểm tra file đầu vào",forecast:"Dự đoán SOH",health:"Sức khỏe & tuổi thọ",fault:"Dấu hiệu lỗi pin",history:"Lịch sử dự đoán",anomalies:"Xu hướng bất thường",evaluation:"Đánh giá mô hình",demo:"Demo pin giữ riêng",bms:"BMS trên xe",quality:"Chất lượng dữ liệu",profile:"Thông tin"};
const names = {"Random Forest":"Random Forest","Ridge-RF residual":"Ridge–RF hiệu chỉnh phần dư",CatBoost:"CatBoost",XGBoost:"XGBoost"};
const phases = {primary:"Sử dụng ban đầu",second_life:"Tái sử dụng"};
const labels = {battery:"Mã pin",cycle:"Chu kỳ",phase:"Giai đoạn",cycles:"Số chu kỳ",soh_min:"SOH thấp nhất (%)",soh_max:"SOH cao nhất (%)",soh_pct:"SOH tham chiếu (%)",capacity_ah:"Dung lượng xả (Ah)",predicted_soh_pct:"SOH dự đoán (%)",absolute_error:"Sai số tuyệt đối (điểm %)",phase_code:"Giai đoạn (0/1)",measurement_count:"Điểm đo",status:"Trạng thái",error:"Lý do",outside_count:"Đặc trưng ngoài miền",time:"Thời gian (s)",terminal_voltage:"Điện áp (V)",terminal_current:"Dòng điện (A)",temperature:"Nhiệt độ (°C)",vehicle:"Xe",session:"Phiên sạc",start:"Bắt đầu",month:"Tháng",reference_soh_pct:"SOH suy ra (%)",reference_capacity_ah:"Dung lượng suy ra (Ah)",reference_sessions:"Phiên tạo nhãn",feature:"Đặc trưng",contribution:"Đóng góp (điểm %)",flag:"Gắn cờ",reason:"Lý do",expected_soh:"Xu hướng từ lịch sử (%)"};
Object.assign(labels,{created_at:"Thời điểm chạy",model:"Mô hình",dataset:"Nguồn",prediction:"SOH ước tính (%)",loss_pct:"Suy giảm ước tính (%)",temp_max_c:"Nhiệt độ cao nhất (°C)",outcome:"Đối chiếu tín hiệu"});
let active="overview", version=0, controller=new AbortController(), exports=new Map(), exportId=0;
const selections={};
function state(page=active){return selections[page] ||= {phase:"primary"};}
// Cache only public read-only JSON; predictions/uploads always reach the server.
const readCacheKey="vincent-public-cache:"+document.querySelector('script[src*="app.js"]')?.getAttribute("src");
let readCache=[];
try{readCache=JSON.parse(sessionStorage.getItem(readCacheKey)||"[]").filter(x=>Date.now()-x.at<120000).slice(-12);}catch(e){readCache=[];}
async function api(url, options={}){
  const cacheable=(!options.method||options.method.toUpperCase()==="GET")&&!options.body&&/^\/api\/(overview|trends|evaluation|thesis-audit|explorer|quality|bms|profile)(\?|$)/.test(url);
  const cached=cacheable&&readCache.find(x=>x.url===url&&Date.now()-x.at<120000);
  if(cached)return structuredClone(cached.data);
  const response=await fetch(url,{...options,signal:controller.signal,headers:{Accept:"application/json",...(options.headers||{})}});
  let data;try{data=await response.json();}catch(e){throw new Error("Máy chủ chưa trả về dữ liệu. Hãy thử lại sau ít phút.");}
  if(!response.ok)throw new Error(data.error||`Lỗi HTTP ${response.status}`);
  if(cacheable){
    const item={url,at:Date.now(),data};
    if(JSON.stringify(item).length<100000){
      readCache=readCache.filter(x=>x.url!==url&&Date.now()-x.at<120000).slice(-11);readCache.push(item);
      try{sessionStorage.setItem(readCacheKey,JSON.stringify(readCache));}catch(e){}
    }
  }
  return data;
}
function header(title,subtitle,eyebrow=""){return `<div class="welcome${eyebrow==="ĐỀ TÀI KHÓA LUẬN"?" thesis-heading":""}">${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:""}<h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>`;}
function panel(title,sub,body){return `<section class="panel"><h2>${esc(title)}</h2>${sub?`<p class="sub">${esc(sub)}</p>`:""}${body}</section>`;}
function notice(text,kind=""){return `<div class="notice ${kind}">${esc(text)}</div>`;}
function kpis(items){return `<div class="kpis">${items.map(x=>`<div class="kpi${x.tone?" "+esc(x.tone):""}"><div class="kpi-label">${esc(x.label)}</div><div class="kpi-value">${x.value==null?"—":typeof x.value==="number"?fmt(x.value,x.digits??3):esc(x.value)}${x.unit?` <small>${esc(x.unit)}</small>`:""}</div><small>${esc(x.detail||"")}</small></div>`).join("")}</div>`;}
function select(id,label,items,current,extra=""){
  return `<div class="field"><label for="${id}">${esc(label)}</label><select id="${id}" ${extra}>${items.map(item=>{const v=typeof item==="object"?item.value:item;const l=typeof item==="object"?item.label:item;return `<option value="${esc(v)}" ${String(v)===String(current)?"selected":""}>${esc(l)}</option>`;}).join("")}</select></div>`;
}
function phaseControl(value){return select("phase","Giai đoạn",Object.entries(phases).map(([value,label])=>({value,label})),value);}
function bindPhase(){const node=$("#phase");if(node)node.onchange=()=>{state().phase=node.value;delete state().cycle;render();};}
function change(id,key,reset=[]){$(id).onchange=()=>{state()[key]=$(id).value;reset.forEach(k=>delete state()[k]);render();};}
function table(rows,title="du_lieu",columns=null){
  if(!rows?.length)return '<div class="empty">Chưa có dòng dữ liệu trong lựa chọn này.</div>';
  const cols=columns||Object.keys(rows[0]), id=String(++exportId);exports.set(id,{rows,cols,title});
  return `<div class="actions"><button class="button small" data-export="${id}">Tải CSV</button><span class="muted">${fmt(rows.length)} dòng${rows.length>500?" · hiển thị 500 dòng đầu":""}</span></div><div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th scope="col">${esc(labels[c]||c)}</th>`).join("")}</tr></thead><tbody>${rows.slice(0,500).map(r=>`<tr>${cols.map(c=>{const v=r[c];return `<td>${esc(typeof v==="number"?fmt(v,5):typeof v==="boolean"?(v?"Có":"Không"):phases[v]||v|| (v===0?0:"—"))}</td>`;}).join("")}</tr>`).join("")}</tbody></table></div>`;
}
function csvDownload(rows,cols,title){
  const cell=v=>{let s=String(v??"");if(typeof v==="string"&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};
  const csv="\uFEFF"+[cols.map(cell).join(","),...rows.map(r=>cols.map(c=>cell(r[c])).join(","))].join("\r\n");
  const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download=title+".csv";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
document.addEventListener("click",event=>{const button=event.target.closest("[data-export]");if(button){const x=exports.get(button.dataset.export);if(x)csvDownload(x.rows,x.cols,x.title);}});
function put(html,token){if(token!==version)return false;$("#content").innerHTML=html;return true;}
function series(name,rows,x,y){return {name,points:rows.map(r=>({x:r[x],y:r[y]}))};}
function chart(id,lines,xLabel="Chu kỳ",yLabel="SOH (%)"){
  const target=document.getElementById(id);if(!target)return;
  const colors=["#219579","#6878d4","#d6993c","#d46687","#3e9cc2","#9d74be"];
  const all=lines.flatMap(l=>l.points.filter(p=>p.x!=null&&p.y!=null&&Number.isFinite(Number(p.y))));
  if(!all.length){target.innerHTML='<div class="empty">Không có đủ điểm để vẽ biểu đồ.</div>';return;}
  const categorical=all.some(p=>typeof p.x!=="number"),categories=[...new Set(all.map(p=>p.x))].sort();
  const valueX=x=>categorical?categories.indexOf(x):Number(x);
  const xs=all.map(p=>valueX(p.x)),ys=all.map(p=>Number(p.y));let minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
  if(minX===maxX)maxX=minX+1;const pad=Math.max((maxY-minY)*.12,.05);minY-=pad;maxY+=pad;
  const W=800,H=300,L=62,R=20,T=18,B=48,pw=W-L-R,ph=H-T-B;
  const sx=x=>L+(valueX(x)-minX)/(maxX-minX)*pw,sy=y=>T+(maxY-y)/(maxY-minY)*ph;
  let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(yLabel)} theo ${esc(xLabel)}">`;
  for(let i=0;i<=4;i++){const y=T+i*ph/4,v=maxY-i*(maxY-minY)/4;svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="${L-9}" y="${y+4}" text-anchor="end">${esc(fmt(v,1))}</text>`;}
  for(let i=0;i<=4;i++){const v=minX+i*(maxX-minX)/4,x=L+i*pw/4,label=categorical?categories[Math.min(categories.length-1,Math.round(v))]:fmt(v,0);svg+=`<text x="${x}" y="${H-24}" text-anchor="middle">${esc(label)}</text>`;}
  lines.forEach((line,i)=>{const valid=line.points.filter(p=>p.y!=null&&Number.isFinite(Number(p.y)));svg+=`<polyline fill="none" stroke="${colors[i%colors.length]}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round" points="${valid.map(p=>`${sx(p.x)},${sy(p.y)}`).join(" ")}"/>`;if(valid.length===1)svg+=`<circle cx="${sx(valid[0].x)}" cy="${sy(valid[0].y)}" r="4" fill="${colors[i%colors.length]}"/>`;});
  svg+=`<text x="${W/2}" y="${H-3}" text-anchor="middle">${esc(xLabel)}</text><text x="${L}" y="11">${esc(yLabel)}</text></svg>`;
  target.innerHTML=svg+`<div class="legend">${lines.map((l,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(l.name)}</span>`).join("")}</div><div class="plot-tooltip" hidden></div>`;
  const tip=$(".plot-tooltip",target),plot=$("svg",target);
  plot.onpointermove=event=>{const rect=plot.getBoundingClientRect(),vx=(event.clientX-rect.left)/rect.width*W;let best=null,dist=Infinity;
    lines.forEach((l,i)=>l.points.forEach(p=>{if(p.y==null)return;const d=Math.abs(sx(p.x)-vx);if(d<dist){dist=d;best={p,l,i};}}));if(!best)return;
    tip.hidden=false;tip.innerHTML=`<strong>${esc(best.l.name)}</strong><br>${esc(xLabel)}: ${esc(best.p.x)}<br>${esc(yLabel)}: ${esc(fmt(best.p.y,3))}`;
    tip.style.left=Math.min(Math.max(event.clientX-rect.left+12,0),Math.max(0,rect.width-210))+"px";tip.style.top="24px";
  };plot.onpointerleave=()=>tip.hidden=true;
}
function bars(id,rows,name,value){const t=document.getElementById(id);if(!t)return;const max=Math.max(...rows.map(r=>Math.abs(Number(r[value]))),.001);t.innerHTML=`<div class="bar-list">${rows.map(r=>`<div class="bar-row"><span>${esc(r[name])}</span><div class="bar-track"><i style="width:${Math.max(1,Math.abs(Number(r[value]))/max*100)}%;${r[value]<0?"background:#d46687":""}"></i></div><span class="bar-value">${fmt(r[value],3)}</span></div>`).join("")}</div>`;}
async function overview(token){
  const s=state(),d=await api(`/api/overview?phase=${s.phase}`);
  if(!put(header("Phân tích và dự đoán tình trạng sức khỏe pin xe điện bằng các mô hình học máy","Tra cứu tín hiệu đo, so sánh mô hình và ước lượng dung lượng còn lại.","ĐỀ TÀI KHÓA LUẬN")+kpis(d.kpis)+`<div class="grid-main">${panel("SOH theo chu kỳ xả","Dung lượng xả tham chiếu / 2,4 Ah",`<div class="controls">${phaseControl(s.phase)}</div><div class="field"><label for="pins">Pin trên biểu đồ · chọn tối đa 6</label><select id="pins" multiple>${d.batteries.map((p,i)=>`<option ${i<4?"selected":""}>${esc(p)}</option>`).join("")}</select></div><div class="plot" id="overview-plot"></div>`)}${panel("Phạm vi thực nghiệm","Hai nguồn dữ liệu, hai mô hình riêng",`<div class="scope-grid"><div><b>86 pin</b><span>Cell SDU · phòng thí nghiệm</span></div><div><b>20 xe</b><span>BMS · BAIC EU500</span></div><div><b>${d.model_count} cấu hình</b><span>So sánh cùng nhóm pin kiểm thử</span></div><div><b>120 giây</b><span>Cửa sổ đầu xả / đầu sạc</span></div></div>${notice("BMS dùng nhãn SOH suy ra từ dòng điện và SOC khi sạc; chưa có phép đo dung lượng độc lập để xác nhận SOH vật lý.")}<p class="sub">${fmt(d.dataset.all_measurement_rows)} điểm đo SDU được giữ trong bản sản phẩm.</p><details><summary>Đề tài khóa luận</summary><p>Phân tích và dự đoán tình trạng sức khỏe pin xe điện bằng các mô hình học máy</p></details>`)}</div>`+panel("Thống kê từng pin",phases[s.phase],table(d.stats,"thong_ke_pin")),token))return;
  bindPhase();const load=async()=>{const pins=[...$("#pins").selectedOptions].map(o=>o.value);if(pins.length<1||pins.length>6){$("#overview-plot").innerHTML=notice("Chọn từ 1 đến 6 pin.");return;}try{const v=await api(`/api/trends?phase=${s.phase}&batteries=${encodeURIComponent(pins.join(","))}`);if(token===version)chart("overview-plot",v.series.map(l=>series(l.name,l.points,"cycle","soh_pct")));}catch(e){if(e.name!=="AbortError")toast(e.message);}};$("#pins").onchange=load;await load();
}
async function explorer(token){
  const s=state(),q=new URLSearchParams({phase:s.phase,...s.battery?{battery:s.battery}:{},...s.cycle?{cycle:s.cycle}:{},full:s.full||"0"}),d=await api("/api/explorer?"+q);
  if(!put(header("Tra cứu và so sánh pin","Xem tín hiệu điện áp, dòng điện và nhiệt độ theo từng chu kỳ.")+panel("Bộ lọc","",`<div class="controls">${phaseControl(s.phase)}${select("battery","Mã pin",d.batteries,d.battery)}${select("cycle","Chu kỳ",d.cycles,d.cycle)}${select("full","Phạm vi",[{value:"0",label:"120 giây đầu"},{value:"1",label:"Toàn bộ đoạn xả"}],s.full||"0")}</div>`)+kpis([{label:"SOH tham chiếu",value:d.summary.soh_pct,unit:"%",detail:"Không phải dự đoán"},{label:"Dung lượng xả",value:d.summary.capacity_ah,unit:"Ah"},{label:"Điểm đo đang xem",value:d.measurement_count},{label:"Chu kỳ",value:d.cycle,detail:d.battery}])+panel("Diễn biến SOH",phases[s.phase],'<div id="explorer-trend" class="plot"></div>')+`<div class="grid-equal">${panel("Điện áp","V",'<div id="voltage" class="plot"></div>')}${panel("Dòng điện","A · dòng xả âm",'<div id="current" class="plot"></div>')}</div>`+panel("Nhiệt độ","°C",'<div id="temperature" class="plot"></div>')+panel("Phép đo chu kỳ","Sau 120 giây dữ liệu được lấy thưa; nhãn dung lượng lấy từ chu kỳ đầy đủ.",`<a class="button" href="/api/download/cycle?phase=${s.phase}&battery=${encodeURIComponent(d.battery)}&cycle=${d.cycle}">Tải toàn bộ CSV chu kỳ</a>${table(d.signals,"tin_hieu_hien_thi")}`)+panel("So sánh SOH giữa các pin","Chọn nhiều pin để đối chiếu đường SOH; khác giai đoạn được xem riêng.",`<div class="field"><label for="compare-pins">Pin cần so sánh · tối đa 6</label><select id="compare-pins" multiple>${d.batteries.map((p,i)=>`<option ${i<3?"selected":""}>${esc(p)}</option>`).join("")}</select></div><div id="compare-plot" class="plot"></div>`),token))return;
  document.querySelector("#content").insertAdjacentHTML("beforeend",panel("So sánh hai chu kỳ","Chọn độc lập pin và giai đoạn A/B; tín hiệu trong 120 giây đầu.",'<div id="cycle-compare"></div>'));await compareCycles(d,token);if(token!==version)return;
  bindPhase();change("#battery","battery",["cycle"]);change("#cycle","cycle");change("#full","full");
  chart("explorer-trend",[series(d.battery,d.trend,"cycle","soh_pct")]);chart("voltage",[series("Điện áp",d.signals,"time","terminal_voltage")],"Thời gian (s)","V");chart("current",[series("Dòng điện",d.signals,"time","terminal_current")],"Thời gian (s)","A");chart("temperature",[series("Nhiệt độ",d.signals,"time","temperature")],"Thời gian (s)","°C");
  const load=async()=>{const pins=[...$("#compare-pins").selectedOptions].map(x=>x.value);if(!pins.length||pins.length>6){$("#compare-plot").innerHTML=notice("Chọn từ 1 đến 6 pin.");return;}try{const r=await api(`/api/trends?phase=${s.phase}&batteries=${encodeURIComponent(pins.join(","))}`);if(token===version)chart("compare-plot",r.series.map(x=>series(x.name,x.points,"cycle","soh_pct")));}catch(e){if(e.name!=="AbortError")toast(e.message);}};$("#compare-pins").onchange=load;await load();
}
function modelVerdict(rows,dataset){
  const sorted=[...rows].sort((a,b)=>a.macro_mae-b.macro_mae),best=sorted[0],rf=sorted.find(r=>r.model==="Random Forest"),gain=(rf.macro_mae-best.macro_mae)/rf.macro_mae*100;
  const ranked=sorted.map((r,i)=>{const delta=r.macro_mae-rf.macro_mae,relative=Math.abs(delta)/rf.macro_mae*100;return {"Hạng MAE":i+1,"Mô hình":names[r.model]||r.model,"MAE ↓":fmt(r.macro_mae,4),"RMSE ↓":fmt(r.macro_rmse,4),"R² ↑":fmt(r.macro_r2,4),"MAE so với Random Forest":r.model==="Random Forest"?"Mốc so sánh":`${delta<0?"Giảm":"Tăng"} ${fmt(Math.abs(delta),4)} điểm % (${fmt(relative,2)}%)`};});
  return panel(`${dataset} · Mô hình nào tốt hơn?`,`${best.groups} ${dataset==="SDU"?"pin":"xe"} · ${fmt(best.samples,0)} mẫu/mô hình · cùng 5 vòng kiểm thử theo nhóm`,
    `<div class="assessment-card"><div class="eyebrow">MAE THẤP NHẤT TRONG CÁC CẤU HÌNH ĐÃ THỬ</div><h2>${esc(names[best.model]||best.model)}</h2><p><strong>MAE ${fmt(rf.macro_mae,4)} → ${fmt(best.macro_mae,4)} điểm % SOH</strong></p><p>Giảm ${fmt(rf.macro_mae-best.macro_mae,4)} điểm % · tương đương giảm <strong>${fmt(gain,2)}% sai số MAE</strong> so với Random Forest.</p><p>${dataset==="SDU"?"Ridge–RF chỉ nhỉnh hơn theo MAE macro. Random Forest có RMSE macro thấp hơn và MAE gộp tốt hơn; chưa có mô hình vượt trội mọi tiêu chí. Ridge–RF giảm MAE trên 40/86 pin; khoảng bootstrap của chênh MAE chứa 0.":"Ridge–RF tốt hơn Random Forest về MAE, RMSE và R² macro trong dữ liệu này; MAE giảm trên 20/20 xe. Đây là mức khớp với nhãn SOH suy ra từ vận hành, chưa kiểm chứng dung lượng đo độc lập."}</p></div>`+
    table(ranked,`xep_hang_${dataset.toLowerCase()}`)+`<p class="sub">Xếp hạng theo MAE macro (trung bình đều theo pin/xe). Mức giảm sai số không phải độ chính xác phần trăm. MAE/RMSE càng thấp càng tốt; R² càng cao càng tốt.</p>`);
}
async function evaluation(token){
  const s=state(),q=new URLSearchParams({...s.model?{model:s.model}:{},...s.battery?{battery:s.battery}:{}}),[d,audit]=await Promise.all([api("/api/evaluation?"+q),api("/api/thesis-audit")]);
  if(!put(header("Đánh giá mô hình","Kiểm thử 5 vòng theo mã pin vật lý; hai giai đoạn của một pin luôn cùng phía.")+modelVerdict(audit.sdu,"SDU")+modelVerdict(audit.bms,"BMS")+panel("Nguồn SOH tham chiếu và tính công bằng","Hai bộ dữ liệu được đánh giá riêng.",`<p><strong>SDU:</strong> dung lượng xả từ dữ liệu nguồn / 2,4 Ah × 100. Đầu vào chỉ dùng tín hiệu 120 giây đầu xả và thông tin giai đoạn/chu kỳ.</p><p><strong>BMS:</strong> tích phân dòng sạc / độ tăng SOC ở phần sau 120 giây; lấy trung vị theo xe–tháng rồi chia 145 Ah × 100. Nhãn phụ thuộc cảm biến và SOC, chưa có đo dung lượng độc lập; nhiều phiên chung nhãn tháng. Đây là đánh giá hồi cứu, không chứng minh dự báo tương lai.</p><p><strong>Cùng tập kiểm thử:</strong> mỗi pin/xe chỉ thuộc một fold, không trùng với tập học. CatBoost/XGBoost có tinh chỉnh bằng validation bên trong tập học; baseline dùng cấu hình cố định và GRU dùng biểu diễn khác, nên ngân sách tinh chỉnh chưa hoàn toàn ngang nhau. Không so trực tiếp MAE giữa SDU và BMS.</p>`)+panel("Kết quả đã kiểm chứng","Tính lại từ dự đoán kiểm thử đã lưu; không phải lượt huấn luyện lại.",`<p>Đã kiểm tra đủ mẫu, không trùng mẫu, đúng nhóm pin/xe và khớp chỉ số công bố.</p><div class="actions"><a class="button primary" href="/api/download/thesis-audit?kind=report">Tải phần kết quả khóa luận</a><a class="button" href="/api/download/thesis-audit?kind=defense">Tải báo cáo & dàn ý bảo vệ</a><a class="button" href="/api/download/thesis-audit?kind=sdu">CSV SDU</a><a class="button" href="/api/download/thesis-audit?kind=bms">CSV BMS</a></div><details><summary>Xem kiểm chứng và giới hạn</summary><h3>SDU · 86 pin · 5 vòng kiểm thử</h3>${table(audit.sdu,"kiem_chung_sdu")}<h3>BMS · 20 xe · 5 vòng kiểm thử</h3>${table(audit.bms,"kiem_chung_bms")}<p>MAE/RMSE có đơn vị điểm % SOH. R² không phải tỷ lệ dự đoán đúng. Macro là trung bình đều theo pin/xe; pooled là tính gộp tất cả mẫu.</p><p>Ridge–RF chỉ hơn Random Forest rất ít trên SDU; chưa kết luận vượt trội. Nhãn BMS suy ra từ dòng điện/SOC, chưa đối chiếu dung lượng đo độc lập. Kết quả không chẩn đoán pin hỏng hoặc xác nhận an toàn.</p><a class="button" href="/api/download/thesis-audit?kind=paired">Tải so sánh theo pin/xe</a><a class="button" href="/api/download/thesis-audit?kind=verification">Tải dấu vết kiểm chứng</a></details>`)+panel("So sánh kết quả","MAE/RMSE nhỏ hơn là tốt hơn. Điểm được lấy trung bình đều theo pin; MAE không phải độ chính xác phần trăm.",table(d.metrics,"so_sanh_mo_hinh"))+panel("Dự đoán trên pin giữ riêng","Mỗi đường dùng kết quả ngoài tập huấn luyện.",`<div class="controls">${select("model","Mô hình",d.models,d.model)}${select("eval-battery","Pin kiểm thử",d.batteries,d.battery)}</div><div id="evaluation-plot" class="plot"></div>`)+`<div class="grid-equal">${panel("Theo giai đoạn","",table(d.phases,"chi_so_giai_doan"))}${panel("Theo pin","",table(d.by_battery,"chi_so_theo_pin"))}</div>`+panel("Thời gian thực nghiệm","Thời gian học và dự đoán theo từng vòng kiểm thử.",table(d.timings,"thoi_gian_mo_hinh")),token))return;
  change("#model","model");change("#eval-battery","battery");chart("evaluation-plot",d.series.flatMap(l=>[series(l.name+" · tham chiếu",l.points,"cycle","actual_soh"),series(l.name+" · dự đoán",l.points,"cycle","predicted_soh")]));
}
async function compareCycles(initial,token){
  const target=$("#cycle-compare"),choice={a:{phase:state().phase,battery:initial.battery,cycle:initial.cycle},b:{phase:state().phase,battery:initial.battery,cycle:initial.cycles[Math.min(1,initial.cycles.length-1)]}},data={};let channel="terminal_voltage",revision=0;
  const channels=[{value:"terminal_voltage",label:"Điện áp (V)"},{value:"terminal_current",label:"Dòng điện (A)"},{value:"temperature",label:"Nhiệt độ (°C)"}];
  async function refresh(){const rev=++revision;try{
    const result=await Promise.all(["a","b"].map(async key=>[key,await api("/api/explorer?"+new URLSearchParams(choice[key]))]));
    if(token!==version||rev!==revision)return;
    result.forEach(([key,d])=>{data[key]=d;choice[key].battery=d.battery;choice[key].cycle=d.cycle;});
    target.innerHTML=`<div class="grid-equal">${["a","b"].map(key=>`<div><h3>Chu kỳ ${key.toUpperCase()}</h3><div class="controls">${select("cmp-phase-"+key,"Giai đoạn",Object.entries(phases).map(([value,label])=>({value,label})),choice[key].phase)}${select("cmp-pin-"+key,"Mã pin",data[key].batteries,data[key].battery)}${select("cmp-cycle-"+key,"Chu kỳ",data[key].cycles,data[key].cycle)}</div><p class="sub">SOH tham chiếu: ${fmt(data[key].summary.soh_pct,3)}% · Dung lượng: ${fmt(data[key].summary.capacity_ah,4)} Ah</p></div>`).join("")}</div><div class="controls">${select("cmp-channel","Tín hiệu",channels,channel)}</div><div id="cycle-compare-plot" class="plot"></div>`;
    function draw(){chart("cycle-compare-plot",["a","b"].map(key=>series(key.toUpperCase()+" · "+data[key].battery+" · chu kỳ "+data[key].cycle,data[key].signals,"time",channel)),"Thời gian (s)",channels.find(x=>x.value===channel).label);}
    for(const key of ["a","b"]){$("#cmp-phase-"+key).onchange=()=>{choice[key].phase=$("#cmp-phase-"+key).value;delete choice[key].cycle;refresh();};$("#cmp-pin-"+key).onchange=()=>{choice[key].battery=$("#cmp-pin-"+key).value;delete choice[key].cycle;refresh();};$("#cmp-cycle-"+key).onchange=()=>{choice[key].cycle=$("#cmp-cycle-"+key).value;refresh();};}
    $("#cmp-channel").onchange=()=>{channel=$("#cmp-channel").value;draw();};draw();
  }catch(e){if(e.name!=="AbortError"&&token===version)target.innerHTML=notice(e.message,"error");}}
  await refresh();
}

function uploadForm(kind){const isBms=kind==="bms",audit=kind==="audit";
  return `<form id="upload-form"><div class="controls">${!audit?select("predict-model","Mô hình",Object.entries(names).filter(([k])=>!isBms||["Random Forest","Ridge-RF residual"].includes(k)).map(([value,label])=>({value,label})),"Random Forest",'name="model"'):""}${!isBms?select("phase-code","Giai đoạn nếu file chưa có",[{value:"0",label:"Sử dụng ban đầu"},{value:"1",label:"Tái sử dụng"}],"0",'name="phase_code"'):""}</div>${!isBms?'<div class="field"><label for="fallback-cycle">Số chu kỳ nếu CSV chưa có cột cycle</label><input id="fallback-cycle" type="number" name="cycle" min="1" step="1" value="1" required></div>':""}<div class="field"><label for="csv-file">CSV${!isBms?" hoặc CSV.GZ":""} · tối đa 20 MiB</label><input id="csv-file" type="file" name="file" accept=".csv,.csv.gz,.gz"></div><label class="check"><input type="checkbox" name="sample" value="1" id="use-sample">Dùng dữ liệu mẫu có sẵn</label>${isBms?'<label class="check"><input type="checkbox" name="configuration" value="BAIC EU500 145Ah">Tôi xác nhận dữ liệu đúng cấu hình BAIC EU500, bộ pin 145 Ah.</label><details class="comparison-settings"><summary>Ngưỡng đối chiếu tùy chọn</summary><p class="sub">Để trống nếu chưa có tài liệu. Các ngưỡng bạn nhập chỉ dùng đối chiếu, không được hệ thống xác minh là giới hạn an toàn của hãng.</p><div class="controls"><div class="field"><label for="limit-temp">Nhiệt độ sạc tối đa (°C)</label><input id="limit-temp" type="number" name="limit_temperature_max" min="-30" max="85" step="0.1" placeholder="Chưa đặt"></div><div class="field"><label for="limit-spread">Chênh điện áp cell tối đa (mV)</label><input id="limit-spread" type="number" name="limit_cell_spread_mv" min="0" max="2500" step="0.1" placeholder="Chưa đặt"></div><div class="field"><label for="limit-soh">Mốc SOH cần kiểm tra (%)</label><input id="limit-soh" type="number" name="limit_soh_min" min="0" max="100" step="0.1" placeholder="Chưa đặt"></div></div><div class="field"><label for="limit-source">Nguồn tài liệu hoặc ý nghĩa của tiêu chí đã nhập</label><input id="limit-source" name="limit_source" maxlength="300" placeholder="Ví dụ: tài liệu cấu hình pin, hoặc tiêu chí nghiên cứu tự chọn"></div></details>':""}<div class="actions"><button class="button primary" type="submit">${audit?"Kiểm tra dữ liệu":"Chạy dự đoán"}</button><a class="button" href="/api/download/sample?kind=${isBms?"bms":"sdu"}">Tải CSV mẫu</a></div></form><div id="form-result" aria-live="polite"></div>`;
}
function bmsAssessment(d){
  const a=d.assessment;
  if(!a)return kpis([{label:"SOH ước tính",value:d.prediction,unit:"%"}])+notice("Đang cập nhật phần đánh giá chi tiết. Hãy tải lại sau khi triển khai xong.");
  const m=a.metrics,condition={unset:"Chưa có ngưỡng",within:"Chưa vượt tiêu chí đã nhập",exceeded:"Vượt tiêu chí đã nhập"};
  const checks=a.indicators.map(r=>({"Chỉ số":r.label,"Giá trị":fmt(r.value,2)+" "+r.unit,"Ngưỡng đã nhập":r.threshold==null?"Chưa đặt":fmt(r.threshold,2)+" "+r.unit,"Đối chiếu":condition[r.status],"Diễn giải":r.explanation}));
  const signals=[
    {"Tín hiệu":"Nhiệt độ cảm biến","Khoảng quan sát":fmt(m.temperature_min_c,1)+"–"+fmt(m.temperature_max_c,1)+" °C"},
    {"Tín hiệu":"Điện áp bộ pin","Khoảng quan sát":fmt(m.pack_voltage_min_v,2)+"–"+fmt(m.pack_voltage_max_v,2)+" V"},
    {"Tín hiệu":"Biên độ dòng sạc","Khoảng quan sát":fmt(m.charge_current_min_a,2)+"–"+fmt(m.charge_current_max_a,2)+" A"},
    {"Tín hiệu":"Điện áp cell nhỏ nhất/lớn nhất","Khoảng quan sát":fmt(m.cell_voltage_min_v,3)+"–"+fmt(m.cell_voltage_max_v,3)+" V"},
    {"Tín hiệu":"Chênh nhiệt độ cảm biến lớn nhất cùng thời điểm","Khoảng quan sát":fmt(m.temperature_spread_max_c,1)+" °C"},
    {"Tín hiệu":"SOC đầu → cuối cửa sổ","Khoảng quan sát":fmt(m.soc_start_pct,1)+"% → "+fmt(m.soc_end_pct,1)+"%"},
    {"Tín hiệu":"Số điểm và khoảng thời gian","Khoảng quan sát":m.measurements+" điểm · 0–"+fmt(m.observed_seconds,1)+" giây đầu sạc"},
  ];
  const missing=a.missing.map(x=>({"Thông tin cần có":x.item,"Hiện có / còn thiếu":x.status,"Vì sao cần":x.purpose,"Cách bổ sung":x.action}));
  const meaning=["Khoảng nhiệt độ cảm biến ghi nhận trong cửa sổ; cần giới hạn sạc của đúng bộ pin để đối chiếu.","Điện áp toàn bộ bộ pin; không phải điện áp của một cell.","Độ lớn dòng điện đang nạp vào pin; không phải dung lượng còn lại.","Giá trị thấp nhất và cao nhất trong cửa sổ; hai cực trị có thể ở hai thời điểm khác nhau. Độ chênh cell phải tính tại cùng thời điểm.","Chênh lệch lớn nhất giữa cảm biến nóng nhất và lạnh nhất tại cùng thời điểm; chưa xác định vị trí cảm biến.","SOC là phần trăm điện đang có; tăng khi sạc. Không dùng SOC thay cho SOH để đánh giá độ chai.","Chỉ mô tả đoạn đầu phiên sạc, không bao quát lúc xe chạy hay toàn bộ tuổi thọ pin."];
  signals.forEach((r,i)=>r["Ý nghĩa và giới hạn"]=meaning[i]);
  const flagged=a.indicators.filter(x=>x.status==="exceeded");
  const status=flagged.length?"Cần kiểm tra: "+flagged.map(x=>x.label.toLowerCase()).join(", "):a.indicators.some(x=>x.status==="unset")?"Chưa có đủ ngưỡng để xếp loại tốt / xấu":"Các chỉ số nằm trong tiêu chí đã nhập";
  return `<section class="assessment-card ${a.level==="review"?"review":""}"><div class="eyebrow">KẾT QUẢ PIN</div><h2>${m.loss_pct==null?"SOH vượt 100% · cần kiểm tra lại dữ liệu":`Pin còn khoảng ${fmt(m.soh_pct,1)}% dung lượng danh định`}</h2><p>${m.loss_pct==null?"Chưa tính mức suy giảm.":`Suy giảm ước tính ${fmt(m.loss_pct,1)}% · tương đương ${fmt(m.capacity_ah,1)} / 145 Ah.`}</p><p><strong>${esc(status)}.</strong></p><p class="sub">Chưa đủ dữ liệu kết luận pin hỏng hay an toàn sử dụng.</p>${d.sample?'<span class="muted">Dữ liệu mẫu minh họa · đã dùng huấn luyện</span>':""}</section>`+
    kpis([{label:"Nhiệt độ cao nhất",value:m.temperature_max_c,digits:1,unit:"°C",tone:a.indicators.find(x=>x.code==="temperature").status==="exceeded"?"attention":"signal",detail:"Thấp nhất "+fmt(m.temperature_min_c,1)+" °C"},
      {label:"Chênh điện áp cell",value:m.cell_spread_max_mv,digits:1,unit:"mV",detail:"Lớn nhất tại cùng thời điểm"},
      {label:"Mức điện hiện tại (SOC)",value:m.soc_end_pct,digits:1,unit:"%",detail:"Cuối cửa sổ đo · khác độ chai"}])+
    (a.alerts.length?notice(a.alerts.map(r=>r.text).join(" "),"warning"):"")+
    `<div class="report-actions actions"><button class="button primary" id="bms-report-html">Tải báo cáo</button></div><details class="bms-more"><summary>Xem đối chiếu, biểu đồ và giải thích chi tiết</summary><p>${esc(a.explanation)}</p><p class="sub">${esc(a.scope)} · ${esc(a.source.label)}${a.source.vehicle?" · "+esc(a.source.vehicle)+" / phiên "+esc(a.source.session):""}</p>`+
    panel("Đối chiếu từng chỉ số: giá trị thực tế so với tiêu chí",a.limits.source?"Nguồn/ghi chú do người dùng nhập: "+a.limits.source:"Ngưỡng là mốc dùng để so sánh: nhiệt độ và độ lệch cell không quá mốc tối đa; SOH không thấp hơn mốc tối thiểu. Chưa có mốc thì chỉ báo số liệu, chưa xếp loại tốt/xấu.",table(checks,"doi_chieu_bms"))+
    `<div class="grid-equal">${panel("Nhiệt độ đầu phiên sạc","Số đo của cảm biến nhỏ nhất và lớn nhất, không phải nhiệt độ toàn bộ tuổi thọ pin.",'<div id="bms-result-temperature" class="plot"></div>')}${panel("Chênh điện áp cell","Chênh giữa điện áp lớn nhất và nhỏ nhất tại cùng thời điểm.",'<div id="bms-result-spread" class="plot"></div>')}</div>`+
    panel("Các tín hiệu đã quan sát và cách hiểu","BMS là Hệ thống quản lý pin (Battery Management System). Các tín hiệu dưới đây được ghi lại từ bộ pin trên xe; web phân tích dữ liệu, không điều khiển hoặc kiểm tra trực tiếp xe.",table(signals,"tin_hieu_tom_tat_bms"))+
    panel("Theo dõi qua các tháng trước",a.history.message,a.history.points.length>=2?`<div id="bms-result-history" class="plot"></div><p class="sub">Thay đổi giữa mốc đầu và cuối đã quan sát: ${fmt(a.history.delta_soh_pp,2)} điểm % SOH suy ra.</p>`:notice("Chưa có đủ hai mốc tháng trước phiên này để mô tả xu hướng."))+
    panel("Còn thiếu gì để kết luận rõ hơn?","Các thông tin chưa có được ghi rõ; hệ thống không tự điền giả định thay cho dữ liệu.",table(missing,"thong_tin_can_bo_sung_bms"))+
    panel("Việc nên đối chiếu tiếp","",`<ul class="assessment-advice">${a.recommendations.map(x=>`<li>${esc(x)}</li>`).join("")}</ul>`)+
    `<details><summary>Báo cáo đầy đủ và dữ liệu cửa sổ hiển thị</summary><p class="sub">Chỉ số tính trên toàn bộ ${m.measurements} điểm; biểu đồ/bảng xem trước giữ điểm cực trị và giới hạn số điểm khi file dày.</p>${table(a.report_rows,"bao_cao_bms")}${table(d.signals,"du_lieu_cua_so_hien_thi_bms")}</details></details>`;
}
function finishBmsResult(d){
  if(!d.assessment)return;
  chart("bms-result-temperature",[series("Cảm biến thấp nhất",d.signals,"time_s","min_temperature"),series("Cảm biến cao nhất",d.signals,"time_s","max_temperature")],"Giây từ đầu sạc","°C");
  chart("bms-result-spread",[series("Chênh điện áp cell",d.signals.map(r=>({time_s:r.time_s,spread_mv:(r.max_cell_voltage-r.min_cell_voltage)*1000})),"time_s","spread_mv")],"Giây từ đầu sạc","mV");
  if(d.assessment.history.points.length>=2)chart("bms-result-history",[series("Nhãn SOH suy ra theo tháng",d.assessment.history.points,"month","soh_pct")],"Tháng trước phiên đang chọn","SOH suy ra (%)");
  $("#bms-report-html").onclick=()=>downloadReport($("#form-result"),"Báo cáo đánh giá BMS · Vincent D");
}
function downloadReport(node,title){
  const copy=node.cloneNode(true);copy.querySelectorAll("details").forEach(n=>n.open=true);copy.querySelectorAll("button,.actions,.plot-tooltip").forEach(n=>n.remove());
  const css=':root{--muted:#59677b;--line:#dce3eb}*{box-sizing:border-box}body{font:16px/1.55 "Times New Roman",serif;color:#243b53;max-width:1100px;margin:25px auto;padding:15px}h1,h2{line-height:1.3}h1{font-size:26px}h2{font-size:21px}.assessment-card,.panel{padding:18px;border:1px solid #dce3eb;border-radius:10px;margin:14px 0}.assessment-card{border-left:4px solid #487e86}.assessment-limit{padding:12px;background:#f1f4f8}.assessment-limit strong,.assessment-limit span{display:block}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.kpi{border:1px solid #dce3eb;padding:12px;border-radius:8px}.kpi-value{font-size:25px;font-weight:bold;color:#157347}.kpi-label,.sub,small{color:#59677b}.notice{padding:12px;border-left:3px solid #7872b3;background:#f6f7fb;margin:12px 0}.legend{font-size:12px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid #dce3eb;padding:8px;text-align:left;white-space:normal;overflow-wrap:anywhere}svg{max-width:100%;height:auto}svg text{font:12px "Times New Roman",serif;fill:#59677b}.grid-equal{display:grid;grid-template-columns:1fr 1fr;gap:12px}[hidden]{display:none!important}@media(max-width:700px){.kpis,.grid-equal{grid-template-columns:1fr 1fr}}@media print{body{margin:0;padding:0}.panel,.kpi{break-inside:avoid}summary{font-weight:bold}a{color:inherit}}';
  const html=`<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><style>${css}</style><body><h1>${esc(title)}</h1><p>Thời điểm xuất: ${esc(new Date().toLocaleString("vi-VN"))}</p>${copy.innerHTML}</body></html>`;
  const url=URL.createObjectURL(new Blob([html],{type:"text/html;charset=utf-8"}));const link=document.createElement("a");link.href=url;link.download="bao_cao_bms_vincent_d.html";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

function bindUpload(kind,token){
  const form=$("#upload-form"),file=$("#csv-file"),sample=$("#use-sample");sample.onchange=()=>{file.disabled=sample.checked;};
  form.onsubmit=async event=>{event.preventDefault();if(!sample.checked&&!file.files.length){toast("Chọn file hoặc bật dữ liệu mẫu.");return;}if(!sample.checked&&file.files[0]?.size>20*1024*1024){toast("File vượt 20 MiB.");return;}
    const button=$("button[type=submit]",form),out=$("#form-result");button.disabled=true;out.innerHTML='<p class="loading" role="status">Đang xử lý dữ liệu…</p>';
    try{const d=await api(kind==="bms"?"/api/bms/predict":kind==="audit"?"/api/audit":"/api/forecast",{method:"POST",body:new FormData(form)});if(token!==version)return;
      if(kind==="audit"){const valid=d.checks.filter(r=>r.status==="Hợp lệ").length;out.innerHTML=kpis([{label:"Điểm đo",value:d.rows},{label:"Chu kỳ hợp lệ",value:valid},{label:"Chu kỳ có lỗi",value:d.checks.length-valid}])+(d.issue?notice(d.issue,"warning"):notice("Đã kiểm tra cấu trúc và các chu kỳ trong file."))+panel("Kết quả từng chu kỳ","",table(d.checks,"kiem_tra_chu_ky"))+panel("Cấu trúc cột","",table(d.schema,"kiem_tra_cot"))+panel("Xem trước dữ liệu","100 dòng đầu",table(d.preview,"xem_truoc"));}
      else if(kind==="bms"){out.innerHTML=bmsAssessment(d);finishBmsResult(d);saveHistory([{model:d.model,dataset:"BMS",prediction:d.prediction,loss_pct:d.assessment?.metrics.loss_pct,temp_max_c:d.assessment?.metrics.temperature_max_c,outcome:d.assessment?.comparison}]);}
      else{const ok=d.results.filter(r=>r.status==="Thành công");out.innerHTML=(d.sample?notice("Dữ liệu mẫu đã tham gia huấn luyện mô hình bàn giao. Xem Demo pin giữ riêng để kiểm thử độc lập."):"")+kpis([{label:"Chu kỳ thành công",value:ok.length},{label:"Chu kỳ có lỗi",value:d.results.length-ok.length},{label:"SOH dự đoán trung bình",value:ok.length?ok.reduce((a,r)=>a+r.predicted_soh_pct,0)/ok.length:null,unit:"%"}])+panel("Kết quả dự đoán",names[d.model],table(d.results,"du_doan_soh"));if(d.explanation){out.innerHTML+=panel("Đóng góp đặc trưng",`Dự đoán = mốc ${fmt(d.explanation.baseline,3)}% + tổng đóng góp. ${d.explanation.method} Không phải quan hệ nhân quả.`,'<div id="effects"></div>');bars("effects",d.explanation.effects,"feature","contribution");}saveHistory(ok.map(r=>({model:d.model,dataset:"SDU",battery:r.battery,cycle:r.cycle,prediction:r.predicted_soh_pct})));}
      if(token===version)out.scrollIntoView({block:"start",behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"});
    }catch(error){if(error.name!=="AbortError"&&token===version)out.innerHTML=notice(error.message,"error");}finally{button.disabled=false;}
  };
}
async function forecast(token){if(!put(header("Dự đoán tình trạng sức khỏe pin","Tải CSV của một hoặc nhiều chu kỳ; dùng 120 giây đầu xả để ước lượng SOH.")+panel("Dữ liệu SDU","Cell NMC(532)/graphite · dung lượng danh định 2,4 Ah",uploadForm("forecast"))+notice("Chỉ dùng với dữ liệu cùng định dạng và điều kiện SDU. Kết quả ngoài miền học cần được kiểm tra; không dùng để kết luận an toàn pin."),token))return;bindUpload("forecast",token);}
