      out.innerHTML=`<section class="assessment-card"><div class="eyebrow">KẾT QUẢ SỨC KHỎE DUNG LƯỢNG</div><h2>SOH ${fmt(r.soh_pct,1)}% · ${r.loss_pct==null?'vượt mốc danh định':`suy giảm ${fmt(r.loss_pct,1)}%`}</h2><p><strong>${r.remaining==null?'Chưa ước tính được thời điểm xuống ngưỡng':r.remaining===0?'Đã chạm ngưỡng đã chọn':`Khoảng ${fmt(r.remaining,0)} ${unit} nữa tới SOH ${fmt(r.threshold,1)}%`}</strong></p><p>${esc(r.message)}</p><p class="sub">${esc(r.fault_status)}</p></section>`+kpis([{label:'Phiên sạc ghi nhận',value:r.charge_sessions,detail:r.charge_sessions==null?'Chưa có nhật ký phiên sạc':'Phiên đủ điều kiện trong lịch sử · không phải tổng cả đời pin'},{label:'Chu kỳ SDU ghi nhận',value:r.recorded_cycles,detail:'Chu kỳ thử nghiệm trong phạm vi đã chọn'},{label:'Mức điện SOC',value:r.soc_pct,unit:r.soc_pct==null?'':'%',detail:r.soc_pct==null?'Lịch sử này không có SOC':'Giá trị cuối được cung cấp · khác SOH'},{label:'Mốc lịch sử cuối',value:r.current_position,unit},{label:'Mốc dùng fit',value:r.fit_samples,detail:'Tối đa 20 mốc gần nhất'}])+panel('Lịch sử và xu hướng',d.source,'<div id="health-plot" class="plot"></div>')+`<details><summary>Phương pháp, kiểm chứng và dữ liệu còn thiếu</summary><p>${esc(r.method)} Xu hướng cần giảm và R² fit ≥ 0,3 mới ngoại suy; đây là quy tắc chất lượng mô hình, không phải ngưỡng an toàn. Không quy đổi chu kỳ thành ngày khi chưa có tần suất sử dụng. Không coi đường ngoại suy là khoảng tin cậy.</p><p>Lịch sử tải lên cần SOH theo cùng cách xác định. SOC chỉ hiển thị nếu có trong CSV; không suy ra từ SOH. Lỗi/hỏng cần mã lỗi BMS, tín hiệu lỗi và kiểm tra xác nhận; dữ liệu hiện tại không hỗ trợ dự báo thời điểm xảy ra sự cố.</p><a href="/api/download/health-validation">Tải kiểm chứng dự báo theo thời gian</a>${table(r.points,'lich_su_suc_khoe')}${table(r.forecast,'ngoai_suy_nguong')}</details>`;
